node -v && node --input-type=module -e '
import { createPushGate } from "./bot.mjs";
import assert from "node:assert/strict";
const u = { id:"u_8841", timeZone:"Asia/Tokyo", quietStart:"22:00", quietEnd:"07:00", dailyCap:3 };
const r = (g,usr,iso)=>g.attempt(usr,new Date(iso));
// Tokyo = UTC+9. 12:00 JST = 03:00Z
let g = createPushGate();
assert.deepEqual(r(g,u,"2026-10-23T03:00:00Z"),{allowed:true,reason:null});
// quiet: 22:00 JST=13:00Z blocked, 21:59 JST allowed; 07:00 JST=22:00Z(prev) allowed, 06:59 blocked
g = createPushGate();
assert.equal(r(g,u,"2026-10-23T13:00:00Z").reason,"quiet_hours");
assert.equal(r(g,u,"2026-10-23T12:59:00Z").allowed,true);
assert.equal(r(g,u,"2026-10-22T21:59:00Z").reason,"quiet_hours");
assert.equal(r(g,u,"2026-10-22T22:00:00Z").allowed,true);
// cap: 3 allowed (one used above at 21:59 JST + 07:00 JST are different local days)
g = createPushGate();
for (const h of ["00","01","02"]) assert.equal(r(g,u,`2026-10-23T${h}:00:00Z`).allowed,true);
assert.equal(r(g,u,"2026-10-23T03:00:00Z").reason,"daily_cap_reached");
// refused (quiet) does not count; next local day resets: 15:00Z = 00:00 JST next day is quiet, 22:00Z = 07:00 JST allowed
assert.equal(r(g,u,"2026-10-23T22:00:00Z").allowed,true);
// local day not UTC day: LA user, 23:30 local Oct 22 and 00:30 local Oct 23 differ
const la = { id:"u2", timeZone:"America/Los_Angeles", quietStart:"01:00", quietEnd:"06:00", dailyCap:1 };
g = createPushGate();
assert.equal(r(g,la,"2026-10-23T06:30:00Z").allowed,true); // 23:30 PDT Oct 22
assert.equal(r(g,la,"2026-10-23T06:45:00Z").reason,"daily_cap_reached");
assert.equal(r(g,la,"2026-10-23T07:30:00Z").allowed,true); // 00:30 PDT Oct 23, new day
// DST end in LA 2026-11-01: 08:59Z=01:59 PDT quiet, 09:00Z=01:00 PST quiet, 14:00Z=06:00 PST allowed
assert.equal(r(g,la,"2026-11-01T09:00:00Z").reason,"quiet_hours");
assert.equal(r(g,la,"2026-11-01T14:00:00Z").allowed,true);
// invalid inputs, per-call settings, independent gates
assert.equal(r(g,{...u,timeZone:"Mars/Base"},"2026-10-23T03:00:00Z").reason,"invalid_time_zone");
assert.equal(r(g,{...u,quietStart:"25:00"},"2026-10-23T03:00:00Z").reason,"invalid_quiet_hours");
assert.equal(r(g,{...u,dailyCap:0},"2026-10-23T03:00:00Z").reason,"daily_cap_reached");
assert.equal(r(createPushGate(),u,"2026-10-23T03:00:00Z").allowed,true);
console.log("ok");
'
